            valueSubtitleStyle: style
        })
    };

    // REDUCER
    public mergeValueIntoState = this.updater((state: PropertyEntryState, value: Partial<PropertyEntryState>) => {
        const newState = produce(state, (draft) => {
          deepmergeInto(draft, value);
        })
        return (newState);
