    this.propertyEntryStore.mergeValueIntoState({
      value: value
    });
  }

  @Input() public set valueStyle(value: string) {
    this.propertyEntryStore.mergeValueIntoState({
      valueStyle: value
    });
  }

  @Input() public set valueIcon(value: IconModel) {
    this.propertyEntryStore.mergeValueIntoState({
      valueIcon: value
    });
  }

