    this.propertyEntryStore.mergeValueIntoState({
      valueSubtitleStyle: value
    });
  }

  @Input() public set valueSubtitleIcon(value: IconModel) {
    this.propertyEntryStore.mergeValueIntoState({
      valueSubtitleIcon: value
    });
  }

